'use strict';

const decimalPattern = /^(0|[1-9]\d*)(\.\d+)?$/;

function parseDecimal(value, field, allowMissing) {
  if (allowMissing && (value === null || value === undefined || value === '')) return null;
  if (typeof value === 'string' && !decimalPattern.test(value)) {
    throw new TypeError(field + ' must be a decimal');
  }
  if (typeof value !== 'string' && typeof value !== 'number') {
    throw new TypeError(field + ' must be a decimal');
  }
  const number = Number(value);
  if (!Number.isFinite(number) || number < 0) {
    throw new TypeError(field + ' must be finite and non-negative');
  }
  return number;
}

function buildConversionView(input) {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new TypeError('input must be an object');
  }
  if (typeof input.source !== 'string' || input.source.trim().length === 0 ||
      typeof input.target !== 'string' || input.target.trim().length === 0 ||
      (input.direction !== 'forward' && input.direction !== 'reverse')) {
    throw new TypeError('invalid conversion fields');
  }

  const amount = parseDecimal(input.amount, 'amount', false);
  const estimatedRate = parseDecimal(input.estimatedRate, 'estimatedRate', true);
  if (estimatedRate === null || amount === 0) return null;
  if (amount <= 0 || estimatedRate <= 0) throw new TypeError('values must be positive');

  const source = input.source.trim();
  const target = input.target.trim();
  const reversed = input.direction === 'reverse';
  const numericRate = estimatedRate;
  if (!Number.isFinite(numericRate) || numericRate <= 0) {
    throw new TypeError('calculated rate is invalid');
  }
  const rate = Number(numericRate.toPrecision(7)).toString();
  const left = reversed ? target : source;
  const right = reversed ? source : target;

  return {
    left,
    right,
    rate,
    text: '1 ' + left + ' = ' + rate + ' ' + right,
    nextDirection: reversed ? 'forward' : 'reverse'
  };
}

module.exports = buildConversionView;

