'use strict';
const assert = require('node:assert/strict');
const buildConversionView = require('./solution');

assert.equal(typeof buildConversionView, 'function');
const input = {
  estimatedRate: '12.3456789', amount: '2.50',
  source: ' USD ', target: ' INR ', direction: 'forward'
};
assert.deepEqual(buildConversionView(input), {
  left: 'USD', right: 'INR', rate: '12.34568',
  text: '1 USD = 12.34568 INR', nextDirection: 'reverse'
});
assert.deepEqual(input, {
  estimatedRate: '12.3456789', amount: '2.50',
  source: ' USD ', target: ' INR ', direction: 'forward'
});

assert.deepEqual(buildConversionView({
  estimatedRate: 4, amount: 1, source: 'A', target: 'B', direction: 'reverse'
}), {
  left: 'B', right: 'A', rate: '0.25', text: '1 B = 0.25 A', nextDirection: 'forward'
});
assert.deepEqual(buildConversionView({
  estimatedRate: 3, amount: 1, source: 'S', target: 'T', direction: 'reverse'
}), {
  left: 'T', right: 'S', rate: '0.3333333', text: '1 T = 0.3333333 S', nextDirection: 'forward'
});
assert.deepEqual(buildConversionView({
  estimatedRate: '1.0000000', amount: '0.01', source: 'X', target: 'Y', direction: 'forward'
}), {
  left: 'X', right: 'Y', rate: '1', text: '1 X = 1 Y', nextDirection: 'reverse'
});

for (const absent of [null, undefined, '']) {
  assert.equal(buildConversionView({ estimatedRate: absent, amount: 2, source: 'A', target: 'B', direction: 'forward' }), null);
}
for (const zero of [0, '0', '0.00']) {
  assert.equal(buildConversionView({ estimatedRate: 2, amount: zero, source: 'A', target: 'B', direction: 'forward' }), null);
}

const badInputs = [null, [], {},
  { estimatedRate: 1, amount: 1, source: '', target: 'B', direction: 'forward' },
  { estimatedRate: 1, amount: 1, source: 'A', target: '  ', direction: 'forward' },
  { estimatedRate: 1, amount: 1, source: 'A', target: 'B', direction: 'sideways' },
  { estimatedRate: 0, amount: 1, source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: -1, amount: 1, source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: Infinity, amount: 1, source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: '01', amount: 1, source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: '1.', amount: 1, source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: 1, amount: -1, source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: 1, amount: '1e2', source: 'A', target: 'B', direction: 'forward' },
  { estimatedRate: 1e-320, amount: 1, source: 'A', target: 'B', direction: 'reverse' }
];
for (const value of badInputs) assert.throws(() => buildConversionView(value), TypeError);
assert.throws(() => buildConversionView({
  estimatedRate: null, amount: 1, source: '', target: 'B', direction: 'forward'
}), TypeError);

